from __future__ import annotations

from sqlalchemy import MetaData

# One naming convention for every constraint and index, set BEFORE any table exists.
# Without it SQLAlchemy/Alembic invent names that differ between machines and runs, so an
# autogenerated downgrade cannot drop what an upgrade created. Keep it stable — changing it renames
# every constraint. No schema here: tables are unqualified and land in the app schema through the
# connection's search_path (see ``engine.py``), so the schema stays a deploy-time setting.
NAMING_CONVENTION = {
    "ix": "ix_%(column_0_label)s",
    "uq": "uq_%(table_name)s_%(column_0_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}

# The single MetaData every table registers on, and Alembic's target for autogenerate.
metadata = MetaData(naming_convention=NAMING_CONVENTION)
